          code: '<div class="code-block-container"><pre class="shiki github-dark" style="background-color:#151e2c;color:#e1e4e8"><code class="code-line" data-line="4"><span class="line"><span style="color:#E1E4E8">&lt;</span><span style="color:#85E89D">ion-button</span><span style="color:#B392F0"> type</span><span style="color:#E1E4E8">=</span><span style="color:#9ECBFF">"submit"</span><span style="color:#B392F0"> fill</span><span style="color:#E1E4E8">=</span><span style="color:#9ECBFF">"solid"</span><span style="color:#E1E4E8">&gt;Submit&lt;/</span><span style="color:#85E89D">ion-button</span><span style="color:#E1E4E8">&gt;</span></span>\n<span class="line"><span style="color:#E1E4E8">&lt;</span><span style="color:#85E89D">ion-button</span><span style="color:#B392F0"> type</span><span style="color:#E1E4E8">=</span><span style="color:#9ECBFF">"button"</span><span style="color:#B392F0"> class</span><span style="color:#E1E4E8">=</span><span style="color:#9ECBFF">"button-submit"</span><span style="color:#B392F0"> fill</span><span style="color:#E1E4E8">=</span><span style="color:#9ECBFF">"solid"</span><span style="color:#E1E4E8">&gt;Continue&lt;/</span><span style="color:#85E89D">ion-button</span><span style="color:#E1E4E8">&gt;</span></span>\n<span class="line"></span></code></pre></div>',
